"use client";
import {useState,useEffect} from "react"; import {ExternalLink,GitBranch,X} from "lucide-react"; import {Project} from "@/data/projects";
function Art({slug}:{slug:string}){let d=slug==='apex'?<><path d="M15 70 45 18l35 52 30-52 35 52M45 18h65"/><rect x="63" y="37" width="33" height="16"/><path d="M68 45h24"/></>:slug==='sonic'?<><rect x="20" y="20" width="120" height="50" rx="5"/><path d="M40 53V37m9 22V30m9 29V24m9 35V30m9 23V37m13 12c8-11 16-11 24 0"/><circle cx="116" cy="43" r="9"/></>:slug==='ping-up'?<><path d="M25 23h52v30H48L35 66V53H25zM87 37h48v30h-12l-13 12V67H87zM77 39h10" strokeDasharray="3 3"/></>:slug==='content-agent'?<><rect x="24" y="20" width="32" height="23"/><rect x="64" y="35" width="32" height="23"/><rect x="104" y="20" width="32" height="23"/><path d="M56 31h8m32 15h8M40 43v22h80V43"/></>:<><path d="M25 24h72v37H52L37 73V61H25zM108 31c13 5 18 18 11 30M114 23c21 9 28 32 16 51M41 42h40m-40 9h28"/></>;return <svg className={`project-art art-${slug}`} viewBox="0 0 160 90" fill="none" aria-hidden="true"><g className="art-lines" stroke="currentColor" strokeWidth="1.5">{d}</g><g className="art-nodes" fill="currentColor"><circle cx="30" cy="26" r="3"/><circle cx="80" cy="52" r="3"/><circle cx="130" cy="30" r="3"/></g></svg>}
function Modal({p,close}:{p:Project;close:()=>void}){useEffect(()=>{let f=(e:KeyboardEvent)=>e.key==='Escape'&&close();addEventListener('keydown',f);return()=>removeEventListener('keydown',f)},[close]);return <div className="modal-backdrop" onMouseDown={close}><section className="modal" role="dialog" aria-modal="true" onMouseDown={e=>e.stopPropagation()}><button className="modal-close" onClick={close} aria-label="Close"><X size={18}/></button><span className="tiny">{p.category} · {p.date}</span><h2>{p.title}</h2><p>{p.description}</p><h3>Engineering highlights</h3><ul>{p.highlights.map(x=><li key={x}>{x}</li>)}</ul><div className="chipset">{p.tags.map(x=><span className="tag" key={x}>{x}</span>)}</div><div className="modal-actions"><a className="btn" href={p.live} target="_blank" rel="noreferrer">Live <ExternalLink size={15}/></a><a className="btn" href={p.github} target="_blank" rel="noreferrer">Source <GitBranch size={15}/></a></div></section></div>}
export function ProjectCard({project:p}:{project:Project}){let [open,setOpen]=useState(false);return <><article className="project"><button className="project-open" onClick={()=>setOpen(true)}><div className="thumb"><Art slug={p.slug}/><span className="art-label">{p.category}</span></div><div className="project-body"><div style={{display:"flex",justifyContent:"space-between",gap:8}}><h3>{p.title}</h3><span className="tiny">{p.date}</span></div><p>{p.description}</p><div className="chipset">{p.tags.slice(0,4).map(x=><span className="tag" key={x}>{x}</span>)}</div></div></button><div className="links"><a target="_blank" rel="noreferrer" href={p.live}>Live <ExternalLink size={12}/></a><a target="_blank" rel="noreferrer" href={p.github}>GitHub <GitBranch size={12}/></a></div></article>{open&&<Modal p={p} close={()=>setOpen(false)}/>}</>}
